(function(root){'use strict';
const finite=n=>Number.isFinite(n)&&Math.abs(n)<=1000,pt=p=>Array.isArray(p)&&p.length===2&&p.every(finite);
function valid(d){return !!d&&typeof d.caption==='string'&&typeof d.description==='string'&&d.caption.length<=300&&d.description.length<=2000&&Array.isArray(d.lines)&&d.lines.length<=60&&d.lines.every(l=>pt(l.a)&&pt(l.b)&&(!l.dashed||typeof l.dashed==='boolean'))&&Array.isArray(d.labels)&&d.labels.length<=50&&d.labels.every(l=>pt(l.at)&&typeof l.text==='string'&&l.text.length<=100)&&(!d.circles||(Array.isArray(d.circles)&&d.circles.length<=12&&d.circles.every(c=>pt(c.center)&&finite(c.radius)&&c.radius>0)))&&(!d.arcs||(Array.isArray(d.arcs)&&d.arcs.length<=12&&d.arcs.every(a=>pt(a.center)&&finite(a.radius)&&a.radius>0&&finite(a.start)&&finite(a.end)&&a.end>a.start&&a.end-a.start<360)));}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function svg(d){if(!valid(d))throw Error('Invalid geometry diagram');const polar=(a,t)=>[a.center[0]+a.radius*Math.cos(t*Math.PI/180),a.center[1]+a.radius*Math.sin(t*Math.PI/180)];return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 320" role="img" aria-label="${escape(d.description)}"><rect width="500" height="320" fill="#242033"/>${d.lines.map(l=>`<line x1="${l.a[0]}" y1="${l.a[1]}" x2="${l.b[0]}" y2="${l.b[1]}" stroke="#e3c585" stroke-width="2.5" ${l.dashed?'stroke-dasharray="7 5"':''}/>`).join('')}${(d.circles||[]).map(c=>`<circle cx="${c.center[0]}" cy="${c.center[1]}" r="${c.radius}" fill="none" stroke="#e3c585" stroke-width="2.5"/>`).join('')}${(d.arcs||[]).map(a=>{const s=polar(a,a.start),e=polar(a,a.end);return `<path d="M${s.join(' ')} A${a.radius} ${a.radius} 0 ${a.end-a.start>180?1:0} 1 ${e.join(' ')}" stroke="#a9c9e3" fill="none" stroke-width="2"/>`;}).join('')}${d.labels.map(l=>`<text x="${l.at[0]}" y="${l.at[1]}" text-anchor="middle" font-family="sans-serif" font-size="20" fill="#f3eee3">${escape(l.text)}</text>`).join('')}</svg>`;}
function render(d){return `<figure class="geometry-figure"><figcaption>${escape(d.caption)}</figcaption>${svg(d)}<details><summary>図の条件を文字で読む</summary><p>${escape(d.description)}</p></details><p class="subtle">模式図です。長さ・角度は問題文と表示された条件を使います。</p></figure>`;}
root.TrailGeometry={valid,svg,render};
})(typeof window==='undefined'?globalThis:window);
